class A {
    int x = 4;

    void greet() {
        System.out.print("A" + x + " ");
    }
}

class B extends A {
    int x = 5;

    void show() {
        System.out.print(x + " " + super.x + " ");
        super.greet();
        greet();
    }
}

class Student {
    String name;
    Student() { System.out.print("S0 "); }
    Student(String name) {
        this.name = name;
        System.out.print("S1 ");
    }
    void print() { System.out.print(name + " "); }
}

class EngineeringStudent extends Student {
    String college;
    EngineeringStudent(String name, String college) {
        super(name);
        this.college = college;
        System.out.print("E ");
    }
    void print() {
        super.print();
        System.out.print(college + " ");
    }
}

class CSEStudent extends EngineeringStudent {
    CSEStudent() {
        super("Aditya", "IIT G");
        System.out.print("C ");
    }
}
